trait Notifier {
    fn user(&self) -> &str;
    fn notify(&self) -> String {
        format!("Alert for {}", self.user())
    }
}

struct Admin {
    name: String,
}

impl Notifier for Admin {
    ⟦slot1⟧
    ⟦slot2⟧
}

fn main() {
    let a = Admin { name: String::from("Alice") };
    assert_eq!(a.notify(), "URGENT Alert for Alice");
}

